-- 03-deploy-sv-and-agents
-- GENERATED by scripts/generate_install_sql.py from semantic_views/*.yaml, agents/*.yaml and agents/router/*.yaml. Do not edit by hand.
-- Run from the repo root: snow sql -c <connection> --enable-templating NONE -f install/03-deploy-sv-and-agents.sql

-- Each semantic view lives in the schema of its data; SV_GAMING_CROSS_DOMAIN (imports the other three)
-- lives in GAME_CATALOG. All agents live in ONTOLOGY_DEMO.AGENTS. Grants for the app role: app/sql/01_app_role.sql.

CREATE SCHEMA IF NOT EXISTS ONTOLOGY_DEMO.AGENTS;

-- Drop importing views before the views they import
DROP SEMANTIC VIEW IF EXISTS ONTOLOGY_DEMO.GAME_CATALOG.SV_GAMING_CROSS_DOMAIN;
DROP SEMANTIC VIEW IF EXISTS ONTOLOGY_DEMO.GAME_SALES.SV_GAME_COMMERCE;
DROP SEMANTIC VIEW IF EXISTS ONTOLOGY_DEMO.GAME_CATALOG.SV_GENRE_TAXONOMY;
DROP SEMANTIC VIEW IF EXISTS ONTOLOGY_DEMO.GAME_CATALOG.SV_GAME_CATALOG;

-- SV_GAME_CATALOG.yaml -> ONTOLOGY_DEMO.GAME_CATALOG.SV_GAME_CATALOG
