-- SV_GENRE_TAXONOMY.yaml -> ONTOLOGY_DEMO.GAME_CATALOG.SV_GENRE_TAXONOMY
CALL SYSTEM$CREATE_SEMANTIC_VIEW_FROM_YAML('ONTOLOGY_DEMO.GAME_CATALOG', $$
# Semantic view ONTOLOGY_DEMO.GAME_CATALOG.SV_GENRE_TAXONOMY
name: SV_GENRE_TAXONOMY
description: 'Business Ontology domain: Genre Taxonomy. Genre classification, rules, hierarchy and roll-up, mechanics, gameplay types, contexts, narrative structures and game similarity; imports SV_GAME_CATALOG
  for GAMES.'
imports:
