-- SV_GAME_COMMERCE.yaml -> ONTOLOGY_DEMO.GAME_SALES.SV_GAME_COMMERCE
CALL SYSTEM$CREATE_SEMANTIC_VIEW_FROM_YAML('ONTOLOGY_DEMO.GAME_SALES', $$
# Semantic view ONTOLOGY_DEMO.GAME_SALES.SV_GAME_COMMERCE
name: SV_GAME_COMMERCE
description: 'Business Ontology domain: Game Commerce. Sales titles, products, transactions, hardware, subscriptions, monetization tags, revenue summaries and platform exclusivity (GAME_SALES). No link
  to the Catalog.'
tables:
- name: CUSTOMERS
  base_table:
    database: ONTOLOGY_DEMO
    schema: GAME_SALES
    table: CUSTOMER_ACCOUNTS
  primary_key:
    columns:
    - CUSTOMER_ID
  dimensions:
  - name: CUSTOMER_ID
    expr: CUSTOMER_ID
    data_type: NUMBER(38,0)
    access_modifier: public_access
  - name: REGION
    expr: REGION
    data_type: VARCHAR(16777216)
    access_modifier: public_access
  - name: STATUS
    expr: STATUS
    data_type: VARCHAR(1)
    access_modifier: public_access
  metrics:
  - name: CUSTOMER_COUNT
    expr: COUNT(customers.CUSTOMER_ID)
    access_modifier: public_access
- name: DIGITAL_PRODUCTS
  base_table:
    database: ONTOLOGY_DEMO
    schema: GAME_SALES
    table: DIGITAL_PRODUCTS
  primary_key:
    columns:
    - DIGITAL_PRODUCT_ID
  dimensions:
  - name: DIGITAL_PRODUCT_ID
    expr: DIGITAL_PRODUCT_ID
    data_type: NUMBER(38,0)
    access_modifier: public_access
  - name: PRODUCT_NAME
    expr: PRODUCT_NAME
    data_type: VARCHAR(16777216)
    access_modifier: public_access
  - name: SKU_CODE
    expr: SKU_CODE
    data_type: VARCHAR(16777216)
    access_modifier: public_access
  - name: STATUS
    expr: STATUS
    data_type: VARCHAR(16777216)
    access_modifier: public_access
  metrics:
  - name: PRODUCT_COUNT
    expr: COUNT(digital_products.DIGITAL_PRODUCT_ID)
    access_modifier: public_access
- name: DIGITAL_TRANSACTIONS
  base_table:
    database: ONTOLOGY_DEMO
    schema: GAME_SALES
    table: DIGITAL_PRODUCT_TRANSACTIONS
  primary_key:
    columns:
    - TRANSACTION_ID
  dimensions:
  - name: TITLE_ID
    expr: TITLE_ID
    data_type: NUMBER(38,0)
    access_modifier: public_access
  - name: TRANSACTION_DATE
    expr: TRANSACTION_TIMESTAMP::DATE
    data_type: DATE
    access_modifier: public_access
  facts:
  - name: GROSS_REVENUE_AMT
    expr: GROSS_REVENUE
    data_type: FLOAT
    access_modifier: public_access
  - name: NET_DEVELOPER_REVENUE_AMT
    expr: NET_DEVELOPER_REVENUE
    data_type: FLOAT
    access_modifier: public_access
  metrics:
  - name: TOTAL_GROSS_REVENUE
    expr: SUM(digital_transactions.gross_revenue_amt)
    access_modifier: public_access
  - name: TOTAL_NET_DEVELOPER_REVENUE
    expr: SUM(digital_transactions.net_developer_revenue_amt)
    access_modifier: public_access
  - name: TRANSACTION_COUNT
    expr: COUNT(digital_transactions.TRANSACTION_ID)
    access_modifier: public_access
- name: HARDWARE_PRODUCTS
  base_table:
    database: ONTOLOGY_DEMO
    schema: GAME_SALES
    table: HARDWARE_PRODUCTS
  primary_key:
    columns:
    - HARDWARE_PRODUCT_ID
  dimensions:
  - name: PRODUCT_NAME
    expr: PRODUCT_NAME
    data_type: VARCHAR(16777216)
    access_modifier: public_access
  - name: PRODUCT_TYPE
    expr: PRODUCT_TYPE
    data_type: VARCHAR(16777216)
    access_modifier: public_access
- name: HARDWARE_SALES
  base_table:
    database: ONTOLOGY_DEMO
    schema: GAME_SALES
    table: HARDWARE_SALES_TRANSACTIONS
  primary_key:
    columns:
    - TRANSACTION_ID
  dimensions:
  - name: REGION
    expr: REGION
    data_type: VARCHAR(16777216)
    access_modifier: public_access
  - name: SALE_DATE
    expr: SALE_TIMESTAMP::DATE
    data_type: DATE
    access_modifier: public_access
  facts:
  - name: HW_GROSS_REVENUE_AMT
    expr: GROSS_REVENUE
    data_type: FLOAT
    access_modifier: public_access
  metrics:
