-- SV_GAMING_CROSS_DOMAIN.yaml -> ONTOLOGY_DEMO.GAME_CATALOG.SV_GAMING_CROSS_DOMAIN
CALL SYSTEM$CREATE_SEMANTIC_VIEW_FROM_YAML('ONTOLOGY_DEMO.GAME_CATALOG', $$
# Semantic view ONTOLOGY_DEMO.GAME_CATALOG.SV_GAMING_CROSS_DOMAIN
name: SV_GAMING_CROSS_DOMAIN
description: 'Composed view used by both demo agents: imports the Game Catalog, Genre Taxonomy and Game Commerce views and adds the strong-key TITLE_GAME join (Sales TITLES.CATALOG_GAME_ID -> Catalog GAMES).'
imports:
- database_name: ONTOLOGY_DEMO
  schema_name: GAME_CATALOG
  name: SV_GAME_CATALOG
- database_name: ONTOLOGY_DEMO
  schema_name: GAME_CATALOG
  name: SV_GENRE_TAXONOMY
- database_name: ONTOLOGY_DEMO
  schema_name: GAME_SALES
  name: SV_GAME_COMMERCE
relationships:
- name: TITLE_GAME
  left_table: TITLES
  right_table: GAMES
  relationship_columns:
  - left_column: CATALOG_GAME_ID
    right_column: GAME_ID

$$);

-- agents/GAMING_BASELINE_AGENT.yaml
CREATE OR REPLACE AGENT ONTOLOGY_DEMO.AGENTS.GAMING_BASELINE_AGENT
  COMMENT = 'Baseline: text-to-SQL over SV_GAMING_CROSS_DOMAIN only (no Business Ontology)'
  PROFILE = '{"display_name": "Gaming Baseline Assistant"}'
  FROM SPECIFICATION $$
# Agent specification for ONTOLOGY_DEMO.AGENTS.GAMING_BASELINE_AGENT
# Baseline for the with/without-ontology test: text-to-SQL over SV_GAMING_CROSS_DOMAIN only (no Business Ontology).
# SV_GAMING_CROSS_DOMAIN imports the catalog, genre and commerce views: every table and view, strong-key join only.
# Deploy: ./install.sh --only 03
models:
  orchestration: auto

orchestration:
  budget:
    seconds: 300
    tokens: 16000

instructions:
  response: |
    You are an analytics assistant for a PlayStation games business.
    Answer with the number first, then a short explanation of how you got it.
  orchestration: |
    Use query_data to answer data questions.

tools:
  - tool_spec:
      type: cortex_analyst_text_to_sql
      name: query_data
      description: "Query the game catalog, genre taxonomy and game sales data."

tool_resources:
  query_data:
    semantic_view: "ONTOLOGY_DEMO.GAME_CATALOG.SV_GAMING_CROSS_DOMAIN"
    execution_environment:
      type: "warehouse"
      warehouse: "COMPUTE_WH"

$$;

-- agents/GAMING_BON_AGENT.yaml
CREATE OR REPLACE AGENT ONTOLOGY_DEMO.AGENTS.GAMING_BON_AGENT
  COMMENT = 'BON agent: native Business Ontology search + text-to-SQL over SV_GAMING_CROSS_DOMAIN'
  PROFILE = '{"display_name": "Gaming BON Assistant"}'
  FROM SPECIFICATION $$
# Agent specification for ONTOLOGY_DEMO.AGENTS.GAMING_BON_AGENT
# Native Business Ontology search + text-to-SQL over SV_GAMING_CROSS_DOMAIN (the same view as the baseline).
# Three settings are required and NOT validated at create time (check with DESCRIBE AGENT):
#   experimental.EnableSnowscopeBusinessOntologySearch: true
#   tools[].tool_spec.type: snowscope_search
#   tool_resources.business_ontology.corpus: businessOntology
# Deploy: ./install.sh --only 03
models:
  orchestration: auto

experimental:
  EnableSnowscopeBusinessOntologySearch: true

orchestration:
  budget:
    seconds: 300
    tokens: 24000

instructions:
  response: |
    You are an analytics assistant for a PlayStation games business with access to governed
    business definitions from Business Ontology. When answering:
    - Show the governed formula or rule from Business Ontology, then the query result.
    - If Business Ontology provides a formula, USE IT to guide your SQL.
    - Pay attention to synonyms (Title = Game, Studio = Developer, Player/Subscriber/Buyer = Customer),
      code mappings (regions, status codes, Y/N flags), identity rules and genre roll-ups.
    - Never invent a formula. If Business Ontology returns no formula, say so.
    - Answer with the number first, then the reasoning.
  orchestration: |
    CRITICAL WORKFLOW for every question:
    STEP 1: Call business_ontology FIRST to get governed definitions, formulas, synonyms and code
    mappings relevant to the question.
    STEP 2: Use that context to decide which tables, columns, codes and identity rules apply
    (e.g. the Game Identity Match Rule, SIE vs Sales region codes, Account Status 'A').
    STEP 3: Call query_data to run the data query, applying the formula and code mappings.
    If the question is purely about definitions or lineage, answer from business_ontology alone.
    If a lookup returns nothing, retry once with a likely synonym, then report the miss.

tools:
  - tool_spec:
      type: snowscope_search
      name: business_ontology
      description: |
        Search Business Ontology for governed business terms, metrics, entities, synonyms and
        code-mapping terms. Returns definitions, formulas and domain context.
        Call this FIRST before any data query.
  - tool_spec:
      type: cortex_analyst_text_to_sql
      name: query_data
      description: "Query the game catalog, genre taxonomy and game sales data."

tool_resources:
  business_ontology:
    corpus: businessOntology
  query_data:
    semantic_view: "ONTOLOGY_DEMO.GAME_CATALOG.SV_GAMING_CROSS_DOMAIN"
    execution_environment:
      type: "warehouse"
      warehouse: "COMPUTE_WH"

$$;

-- agents/router/GAMING_CATALOG_AGENT.yaml
CREATE OR REPLACE AGENT ONTOLOGY_DEMO.AGENTS.GAMING_CATALOG_AGENT
  COMMENT = 'Router demo: Game Catalog domain agent over SV_GAME_CATALOG'
  PROFILE = '{"display_name": "Gaming Catalog Agent"}'
  FROM SPECIFICATION $$
# Agent specification for ONTOLOGY_DEMO.AGENTS.GAMING_CATALOG_AGENT
# Game Catalog domain: text-to-SQL over SV_GAME_CATALOG only. Routed to by GAMING_ROUTER_AGENT.
# Deploy: ./install.sh --only 03
models:
  orchestration: auto

orchestration:
  budget:
    seconds: 60
    tokens: 16000

instructions:
  response: |
    You are the Game Catalog specialist for a PlayStation games business.
    Answer with the number first, then a short explanation of how you got it.
  orchestration: |
    You answer questions about catalog games: game names, developers, publishers, franchises,
    release dates, lifecycle status (released, remastered, delisted) and point of view.
    Use query_data for every data question.
    You have no revenue, sales, customer, region or genre data. If a question needs any of
    those, do not guess and do not answer from general knowledge: reply that it is outside
    the Game Catalog domain and name what is missing.

tools:
  - tool_spec:
      type: cortex_analyst_text_to_sql
      name: query_data
      description: "Query the game catalog: games, developers, publishers, franchises, release dates and lifecycle status."

tool_resources:
  query_data:
    semantic_view: "ONTOLOGY_DEMO.GAME_CATALOG.SV_GAME_CATALOG"
    execution_environment:
      type: "warehouse"
      warehouse: "COMPUTE_WH"

$$;

-- agents/router/GAMING_GENRE_AGENT.yaml
CREATE OR REPLACE AGENT ONTOLOGY_DEMO.AGENTS.GAMING_GENRE_AGENT
  COMMENT = 'Router demo: Genre Taxonomy domain agent over SV_GENRE_TAXONOMY'
  PROFILE = '{"display_name": "Gaming Genre Agent"}'
  FROM SPECIFICATION $$
# Agent specification for ONTOLOGY_DEMO.AGENTS.GAMING_GENRE_AGENT
# Genre Taxonomy domain: text-to-SQL over SV_GENRE_TAXONOMY only (imports SV_GAME_CATALOG for games).
# Deploy: ./install.sh --only 03
models:
  orchestration: auto

orchestration:
  budget:
    seconds: 60
    tokens: 16000

instructions:
  response: |
    You are the Genre Taxonomy specialist for a PlayStation games business.
    Answer with the number first, then a short explanation of how you got it.
  orchestration: |
    You answer questions about game genres: which games belong to a genre, game counts by
    genre, parent genres and subgenres (the genre roll-up), and genre match status.
    Use query_data for every data question.
    You have no revenue, sales, customer or region data. If a question needs any of those
    (for example revenue by genre), do not guess: reply that it is outside the Genre Taxonomy
    domain and name what is missing.

tools:
  - tool_spec:
      type: cortex_analyst_text_to_sql
      name: query_data
      description: "Query game genres: genre classification, genre roll-up (parent genres) and the catalog games they classify."

tool_resources:
  query_data:
    semantic_view: "ONTOLOGY_DEMO.GAME_CATALOG.SV_GENRE_TAXONOMY"
    execution_environment:
      type: "warehouse"
      warehouse: "COMPUTE_WH"

$$;

