# Agent specification for ONTOLOGY_DEMO.AGENTS.GAMING_SALES_AGENT
# Game Commerce domain: text-to-SQL over SV_GAME_COMMERCE only (no link to the Catalog).
# Deploy: ./install.sh --only 03
models:
  orchestration: auto

orchestration:
  budget:
    seconds: 60
    tokens: 16000

instructions:
  response: |
    You are the Sales (Game Commerce) specialist for a PlayStation games business.
    Answer with the number first, then a short explanation of how you got it.
  orchestration: |
    You answer questions about sales: digital, hardware and subscription revenue, customers
    and their regions and account status, digital products and SKUs, revenue types, store
    platforms, platform exclusivity, and Sales titles.
    Use query_data for every data question.
    You have no catalog attributes (developer, franchise, catalog release data) and no genres.
    If a question needs those, do not guess: reply that it is outside the Sales domain and
    name what is missing.

tools:
  - tool_spec:
      type: cortex_analyst_text_to_sql
      name: query_data
      description: "Query sales: digital, hardware and subscription revenue, customers, regions, products, SKUs, revenue types and exclusivity."

tool_resources:
  query_data:
    semantic_view: "ONTOLOGY_DEMO.GAME_SALES.SV_GAME_COMMERCE"
    execution_environment:
      type: "warehouse"
      warehouse: "COMPUTE_WH"

$$;

-- agents/router/GAMING_ROUTER_AGENT.yaml
CREATE OR REPLACE AGENT ONTOLOGY_DEMO.AGENTS.GAMING_ROUTER_AGENT
  COMMENT = 'Router demo: delegates to the catalog, genre, sales and baseline agents (agent_router)'
  PROFILE = '{"display_name": "Gaming Router Agent"}'
  FROM SPECIFICATION $$
# Agent specification for ONTOLOGY_DEMO.AGENTS.GAMING_ROUTER_AGENT
# Front door: routes each question to the domain agent that owns it (agent_router, preview/undocumented).
# It has no data tools of its own. Deploy (after the four domain agents): ./install.sh --only 03
models:
  orchestration: auto

orchestration:
  budget:
    seconds: 300
    tokens: 32000

instructions:
  response: |
    You are the front door for a PlayStation games analytics team.
    Give the specialist's answer with the number first, then a short explanation, and say which
    specialist(s) answered. When you called several specialists, combine their answers into one reply.
  orchestration: |
    Always answer data questions by routing to a specialist with agent_router. Never answer a
    data question yourself and never invent numbers.
    Routing rules:
    - Catalog agent: catalog games, developers, publishers, franchises, release dates, lifecycle status.
    - Genre agent: genre membership, game counts by genre, parent genres and subgenres.
    - Sales agent: revenue (digital, hardware, subscription), customers, regions, products, SKUs,
      revenue types, exclusivity, when no catalog attribute or genre is needed.
    - Cross-domain agent: any question that combines revenue, sales or customers with a developer,
      publisher, franchise, genre or catalog game (for example revenue by developer or by genre).
    If a question has independent parts that belong to different specialists, call those
    specialists in parallel and combine the answers. If a specialist says the question is outside
    its domain, route it to the specialist that owns the missing data.

tools:
  - tool_spec:
      type: agent_router
      name: agent_router

tool_resources:
  agent_router:
    subagents:
      - name: ONTOLOGY_DEMO.AGENTS.GAMING_CATALOG_AGENT
        display_name: Catalog agent
        description: "Game Catalog domain (SV_GAME_CATALOG). Route questions about catalog games, developers, publishers, franchises, release dates and lifecycle status (released, remastered, delisted). Has no revenue, customer or genre data."
        source:
          type: DATA_AGENT
          fqn: ONTOLOGY_DEMO.AGENTS.GAMING_CATALOG_AGENT
          sample_questions:
            - "How many games has Santa Monica Studio developed?"
            - "Which games are in the God of War franchise?"
            - "How many catalog games are delisted?"
      - name: ONTOLOGY_DEMO.AGENTS.GAMING_GENRE_AGENT
        display_name: Genre agent
        description: "Genre Taxonomy domain (SV_GENRE_TAXONOMY). Route questions about which games belong to a genre, game counts by genre, and parent genres or subgenres. Has no revenue or sales data."
        source:
          type: DATA_AGENT
          fqn: ONTOLOGY_DEMO.AGENTS.GAMING_GENRE_AGENT
          sample_questions:
            - "How many RPG games are there?"
            - "Which genres have the most games?"
            - "What are the subgenres of Action?"
      - name: ONTOLOGY_DEMO.AGENTS.GAMING_SALES_AGENT
        display_name: Sales agent
        description: "Game Commerce domain (SV_GAME_COMMERCE). Route questions about digital, hardware and subscription revenue, customers, regions, account status, products and SKUs, revenue types and platform exclusivity, when no developer, franchise or genre is involved."
        source:
          type: DATA_AGENT
          fqn: ONTOLOGY_DEMO.AGENTS.GAMING_SALES_AGENT
          sample_questions:
            - "What was hardware revenue in North America?"
            - "How many active customers do we have?"
            - "How much revenue came from battle passes?"
      - name: ONTOLOGY_DEMO.AGENTS.GAMING_BASELINE_AGENT
        display_name: Cross-domain agent
        description: "Cross-domain baseline agent (SV_GAMING_CROSS_DOMAIN, imports catalog, genre and commerce). Route questions that combine revenue, sales or customers with a developer, publisher, franchise, genre or catalog game, such as revenue by developer, by franchise or by genre."
        source:
          type: DATA_AGENT
          fqn: ONTOLOGY_DEMO.AGENTS.GAMING_BASELINE_AGENT
          sample_questions:
            - "Which developer earned the most revenue?"
            - "How much revenue did the God of War franchise make?"
            - "Which genre has the most revenue?"

$$;

-- Re-apply ONTOLOGY_APP_ROLE grants on the objects recreated above
CREATE ROLE IF NOT EXISTS ONTOLOGY_APP_ROLE;
GRANT SELECT, REFERENCES ON SEMANTIC VIEW ONTOLOGY_DEMO.GAME_CATALOG.SV_GAME_CATALOG TO ROLE ONTOLOGY_APP_ROLE;
GRANT SELECT, REFERENCES ON SEMANTIC VIEW ONTOLOGY_DEMO.GAME_CATALOG.SV_GENRE_TAXONOMY TO ROLE ONTOLOGY_APP_ROLE;
GRANT SELECT, REFERENCES ON SEMANTIC VIEW ONTOLOGY_DEMO.GAME_SALES.SV_GAME_COMMERCE TO ROLE ONTOLOGY_APP_ROLE;
GRANT SELECT, REFERENCES ON SEMANTIC VIEW ONTOLOGY_DEMO.GAME_CATALOG.SV_GAMING_CROSS_DOMAIN TO ROLE ONTOLOGY_APP_ROLE;
GRANT USAGE ON ALL AGENTS IN SCHEMA ONTOLOGY_DEMO.AGENTS TO ROLE ONTOLOGY_APP_ROLE;
